// Paginate through ALL conversations using nextPage
const locationId = '9oW28j2SxdPAmUhO5MDI';
const allConversations = [];
let nextPage = null;
let page = 0;

do {
  page++;
  let url = `https://services.leadconnectorhq.com/conversations/search?locationId=${locationId}&limit=100`;
  if (nextPage) {
    url += `&startAfterId=${nextPage}`;
  }

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'Authorization': 'Bearer pit-7af79179-2a7e-455f-a685-1b7c15d55547',
      'Version': '2021-07-28'
    },
    json: true
  });

  const conversations = response.conversations || [];
  allConversations.push(...conversations);
  nextPage = response.nextPage || null;

  // Safety: rate limit pause
  if (nextPage) {
    await new Promise(resolve => setTimeout(resolve, 500));
  }
} while (nextPage);

if (allConversations.length === 0) {
  throw new Error('No conversations found for this location.');
}

// Output each conversation as a separate item
return allConversations.map(conv => ({
  json: {
    conversationId: conv.id,
    contactId: conv.contactId || '',
    locationId,
    contactName: conv.contactName || conv.fullName || '',
    lastMessageDate: conv.lastMessageDate || ''
  }
}));

// Build the full conversation TXT, identify valid call messages, and prepare contact info
// Reference source nodes directly to avoid merge data-loss issues
const messagesInput = $('Get Conversation Messages').first().json;
const contactInput = $('Get Contact Info').first().json;
const convData = $('Loop Conversations').first().json;

// Extract messages - handle various GHL API response formats
const messagesRaw = messagesInput.messages || messagesInput.data?.messages || messagesInput.data || [];
const messages = Array.isArray(messagesRaw) ? messagesRaw : [];

// Extract contact info
const contact = contactInput.contact || contactInput;
const firstName = (contact.firstName || contact.first_name || 'unknown').toLowerCase().trim();
const lastName = (contact.lastName || contact.last_name || 'unknown').toLowerCase().trim();

// Sort messages chronologically
const sorted = [...messages].sort((a, b) => {
  const dateA = new Date(a.dateAdded || a.createdAt || 0);
  const dateB = new Date(b.dateAdded || b.createdAt || 0);
  return dateA - dateB;
});

// Build conversation TXT
const lines = sorted.map(msg => {
  const date = new Date(msg.dateAdded || msg.createdAt || new Date());
  const ts = date.toISOString().replace('T', ' ').substring(0, 16);
  const msgType = msg.type || msg.messageType || 'UNKNOWN';
  const direction = msg.direction || 'unknown';
  let body = msg.body || '';

  // For call messages, format with call metadata
  if (msgType === 'TYPE_CALL' || msg.messageType === 'TYPE_CALL') {
    const duration = msg.meta?.call?.duration || msg.meta?.duration || 0;
    const status = msg.meta?.call?.status || msg.status || 'unknown';
    body = `Call - ${duration} seconds - ${status}`;
    if (msg.body && msg.body.trim()) {
      body += ` | ${msg.body.trim()}`;
    }
  }

  return `[${ts}] ${msgType} (${direction}): ${body}`;
});

const conversationTxt = lines.join('\n');

// Find valid call messages: TYPE_CALL with duration > 30
const validCalls = sorted.filter(msg => {
  const msgType = msg.type || msg.messageType || '';
  if (msgType !== 'TYPE_CALL') return false;
  const duration = msg.meta?.call?.duration || msg.meta?.duration || 0;
  return duration > 30;
});

// Determine the earliest message date for filename
const earliestDate = sorted.length > 0
  ? new Date(sorted[0].dateAdded || sorted[0].createdAt || new Date())
  : new Date();
const dateStr = earliestDate.toISOString().split('T')[0];

const baseFilename = `${firstName}-${lastName}_${dateStr}`;

return [{
  json: {
    conversationId: convData.conversationId,
    contactId: convData.contactId,
    firstName,
    lastName,
    baseFilename,
    dateStr,
    conversationTxt,
    validCalls: validCalls.map(c => ({
      messageId: c.id,
      dateAdded: c.dateAdded || c.createdAt || '',
      duration: c.meta?.call?.duration || c.meta?.duration || 0
    })),
    hasValidCalls: validCalls.length > 0
  }
}];

// Pass through data and set subaccount name for folder search
const data = $input.first().json;
return [{
  json: {
    ...data,
    subaccountName: 'Strong Pilates Lakeview'
  }
}];

// Check if the folder was found; if not, flag for creation
const searchResult = $input.first().json;
const files = searchResult.files || [];
const uploadData = $('Prepare Upload Data').first().json;

if (files.length > 0) {
  return [{
    json: {
      folderId: files[0].id,
      folderName: files[0].name,
      baseFilename: uploadData.baseFilename,
      conversationTxt: uploadData.conversationTxt,
      subaccountName: uploadData.subaccountName,
      conversationId: uploadData.conversationId,
      contactId: uploadData.contactId,
      firstName: uploadData.firstName,
      lastName: uploadData.lastName,
      dateStr: uploadData.dateStr,
      validCalls: uploadData.validCalls,
      hasValidCalls: uploadData.hasValidCalls,
      needsCreation: false
    }
  }];
} else {
  return [{
    json: {
      folderId: null,
      folderName: uploadData.subaccountName,
      baseFilename: uploadData.baseFilename,
      conversationTxt: uploadData.conversationTxt,
      subaccountName: uploadData.subaccountName,
      conversationId: uploadData.conversationId,
      contactId: uploadData.contactId,
      firstName: uploadData.firstName,
      lastName: uploadData.lastName,
      dateStr: uploadData.dateStr,
      validCalls: uploadData.validCalls,
      hasValidCalls: uploadData.hasValidCalls,
      needsCreation: true
    }
  }];
}

// After creating the folder, set the folderId from the response
const createResult = $input.first().json;
const prevData = $('Check Folder Exists').first().json;

return [{
  json: {
    folderId: createResult.id,
    folderName: prevData.subaccountName,
    baseFilename: prevData.baseFilename,
    conversationTxt: prevData.conversationTxt,
    subaccountName: prevData.subaccountName,
    conversationId: prevData.conversationId,
    contactId: prevData.contactId,
    firstName: prevData.firstName,
    lastName: prevData.lastName,
    dateStr: prevData.dateStr,
    validCalls: prevData.validCalls,
    hasValidCalls: prevData.hasValidCalls
  }
}];

// Normalize the folder data from either path (existing or newly created)
const data = $input.first().json;
return [{
  json: {
    folderId: data.folderId,
    folderName: data.folderName,
    baseFilename: data.baseFilename,
    conversationTxt: data.conversationTxt,
    subaccountName: data.subaccountName,
    conversationId: data.conversationId,
    contactId: data.contactId,
    firstName: data.firstName,
    lastName: data.lastName,
    dateStr: data.dateStr,
    validCalls: data.validCalls,
    hasValidCalls: data.hasValidCalls
  }
}];

// Create the conversation TXT as binary and upload to Google Drive
const data = $input.first().json;
const conversationTxt = data.conversationTxt;
const filename = `${data.baseFilename}_conversation.txt`;

const buffer = Buffer.from(conversationTxt || '(No messages)', 'utf-8');

return [{
  json: {
    ...data,
    convFilename: filename
  },
  binary: {
    conversationFile: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename
    }
  }
}];

// Output each valid call as a separate item for the inner loop
const data = $('Build Conversation & Find Calls').first().json;
const folderData = $('Normalize Folder Data').first().json;

return data.validCalls.map(call => ({
  json: {
    messageId: call.messageId,
    dateAdded: call.dateAdded,
    duration: call.duration,
    conversationId: data.conversationId,
    contactId: data.contactId,
    firstName: data.firstName,
    lastName: data.lastName,
    baseFilename: data.baseFilename,
    folderId: folderData.folderId,
    folderName: folderData.folderName
  }
}));

// Extract recording URL and check if valid
const response = $input.first().json;
const callData = $('Loop Valid Calls').first().json;

const recordingUrl = response.url || response.recordingUrl || response.recording_url || response.data?.url || '';

if (!recordingUrl) {
  console.log(`No recording found for messageId=${callData.messageId}, conversationId=${callData.conversationId}`);
  return [{
    json: {
      ...callData,
      hasRecording: false,
      recordingUrl: '',
      skipReason: 'No recording URL returned (404 or empty)'
    }
  }];
}

return [{
  json: {
    ...callData,
    hasRecording: true,
    recordingUrl
  }
}];

// Log: no recording for this call
const data = $json;
console.log(`SKIP: No recording for messageId=${data.messageId}, contactId=${data.contactId}, conversationId=${data.conversationId}`);
return [{
  json: {
    status: 'skipped',
    reason: data.skipReason || 'No recording found',
    messageId: data.messageId,
    contactId: data.contactId,
    conversationId: data.conversationId,
    timestamp: new Date().toISOString()
  }
}];

// Build filename for this specific call recording
const callData = $('Has Recording?').first().json;
const callDate = new Date(callData.dateAdded || new Date());
const dateStr = callDate.toISOString().split('T')[0];
const callFilename = `${callData.firstName}-${callData.lastName}_${dateStr}`;

return [{
  json: {
    ...callData,
    callFilename,
    callDateStr: dateStr
  },
  binary: $input.first().binary
}];

// Log transcription failure
const callData = $('Build Call Filename').first().json;
console.log(`TRANSCRIPTION FAILED: messageId=${callData.messageId}, contactId=${callData.contactId}, conversationId=${callData.conversationId}`);
return [{
  json: {
    status: 'error',
    reason: 'Transcription failed or returned no words',
    messageId: callData.messageId,
    contactId: callData.contactId,
    conversationId: callData.conversationId,
    filename: callData.callFilename,
    timestamp: new Date().toISOString()
  }
}];

// Format ElevenLabs Scribe transcript into timestamped dialogue
// Speaker 0 = Rep, Speaker 1 = Lead
const transcriptionData = $('Transcribe with ElevenLabs').first().json;
const callData = $('Build Call Filename').first().json;

const words = transcriptionData.words || [];

if (words.length === 0) {
  return [{
    json: {
      transcript: '(No speech detected)',
      callFilename: callData.callFilename,
      folderId: callData.folderId
    }
  }];
}

// Group words into utterances by speaker changes
const utterances = [];
let currentSpeaker = null;
let currentWords = [];
let currentStart = 0;

for (const word of words) {
  const speaker = word.speaker_id !== undefined ? word.speaker_id : (word.speaker ?? null);

  if (speaker !== currentSpeaker && currentWords.length > 0) {
    utterances.push({
      speaker: currentSpeaker,
      text: currentWords.join(' '),
      start: currentStart
    });
    currentWords = [];
  }

  if (currentWords.length === 0) {
    currentStart = word.start_time || word.start || 0;
    currentSpeaker = speaker;
  }

  currentWords.push(word.text || word.word || '');
}

if (currentWords.length > 0) {
  utterances.push({
    speaker: currentSpeaker,
    text: currentWords.join(' '),
    start: currentStart
  });
}

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
  const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
  const s = Math.floor(seconds % 60).toString().padStart(2, '0');
  return `[${h}:${m}:${s}]`;
}

const lines = utterances.map(u => {
  const speakerNum = parseInt(u.speaker, 10);
  let label;
  if (speakerNum === 0) {
    label = 'Rep';
  } else if (speakerNum === 1) {
    label = 'Lead';
  } else {
    label = `Speaker ${u.speaker}`;
  }
  return `${formatTime(u.start)} ${label}: ${u.text.trim()}`;
});

const transcript = lines.join('\n');

return [{
  json: {
    transcript,
    callFilename: callData.callFilename,
    folderId: callData.folderId
  }
}];

// Convert transcript text to binary TXT for upload
const data = $input.first().json;
const transcript = data.transcript;
const filename = `${data.callFilename}_transcript.txt`;

const buffer = Buffer.from(transcript, 'utf-8');

return [{
  json: {
    transcriptFilename: filename,
    folderId: data.folderId
  },
  binary: {
    transcriptFile: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename
    }
  }
}];

// Rate limit delay between call processing
await new Promise(resolve => setTimeout(resolve, 500));
return $input.all();
